/** A citation is generated by the document service, never trusted from model output. */
export interface AiCitation {
  sourceId: string
  title: string
  url: string
  contentHash?: string
  revision?: string
}

/** Small, display-only metadata derived locally; never a raw tool payload or model-supplied summary. */
export interface AiToolCallOverview {
  input: { label: string; value: string }[]
  summary?: string
  items?: string[]
  note?: string
}
